from (values
('127.153.d.1.A',3,'Color, line, shape, and texture are among the:','["Elements of design", "Safety rules", "Sales tactics", "Building codes"]'::jsonb,0,'Elements are the building blocks of a room.','original'),
('127.153.d.1.A',4,'Which is a principle of design rather than an element?','["Color", "Balance", "Line", "Texture"]'::jsonb,1,'Balance, rhythm, emphasis, proportion, and harmony are principles.','original'),
('127.153.d.1.B',3,'Using dark, warm colors on all walls of a small room usually makes it feel:','["Colder", "Outdoors", "Smaller and cozier", "Much larger"]'::jsonb,2,'Dark warm colors advance.','original'),
('127.153.d.1.B',4,'Tall vertical lines in a room, such as striped drapes, create the effect of:','["Greater width", "Less light", "More noise", "Greater height"]'::jsonb,3,'Vertical lines draw the eye upward.','original'),
('127.153.d.1.C',3,'To coordinate furnishings in a living room, a designer repeats a color or pattern to create:','["Unity and harmony", "Randomness", "Clutter", "Conflict"]'::jsonb,0,'Repetition ties a room together.','original'),
('127.153.d.1.C',4,'A sofa, chair, and rug all share a blue accent so the room feels connected. This uses the principle of:','["Contrast through opposites", "Rhythm through repetition", "Subtraction", "Isolation"]'::jsonb,1,'Repeating a color creates rhythm.','original'),
('127.153.d.1.D',3,'Which factor most directly shapes how a family wants its home designed?','["The color of the car", "The weather forecast", "Cultural traditions and lifestyle", "The brand of a pen"]'::jsonb,2,'Culture influences design preferences.','original'),
('127.153.d.1.D',4,'Open floor plans became popular largely because families wanted more:','["Closed formal rooms", "Dark hallways", "Smaller windows", "Casual, shared living space"]'::jsonb,3,'Social trends drive layout.','original'),
('127.153.d.2.A',3,'When choosing a sofa fabric for a home with young children, the best quality to compare is:','["Durability and stain resistance", "Rarity of the dye", "Brand of the loom", "Weight of the box"]'::jsonb,0,'Fabric must handle wear.','original'),
('127.153.d.2.A',4,'Tight, even stitching and a hardwood frame are signs of good:','["Advertising", "Workmanship", "Shipping", "Packaging"]'::jsonb,1,'Construction quality shows in joinery and stitching.','original'),
('127.153.d.2.B',3,'Solid wood, veneer, and laminate are different kinds of:','["Light bulbs", "Window shades", "Furniture surface materials", "Paint rollers"]'::jsonb,2,'Materials vary in cost and durability.','original'),
('127.153.d.2.B',4,'A piece with a thin wood layer glued over a core of another material uses:','["Metal plating", "Laminate plastic only", "Solid wood", "Veneer"]'::jsonb,3,'Veneer is a thin real wood layer.','original'),
('127.153.d.2.C',3,'Fabric care labels on upholstery use codes like W or S to tell you:','["How the fabric should be cleaned", "Its price", "Who sold it", "Where it was shipped"]'::jsonb,0,'Codes give cleaning method.','original'),
('127.153.d.2.C',4,'An upholstery code of S means the fabric should be cleaned with:','["Plain water only", "A water-free solvent only", "Bleach", "Steam only"]'::jsonb,1,'S means solvent only.','original'),
('127.153.d.2.D',3,'Before using a new appliance, the owner should read the:','["Box color", "Receipt only", "Use and care manual", "Advertisement"]'::jsonb,2,'Manuals explain safe use and upkeep.','original'),
('127.153.d.2.D',4,'A manual''s warranty section tells you:','["Its popularity", "How to paint the item", "Where to hang it", "What repairs the maker will cover and for how long"]'::jsonb,3,'Warranties limit coverage.','original'),
('127.153.d.2.E',3,'A wood table should be dusted with a soft cloth because rough rags can:','["Scratch the finish", "Warp the legs", "Soften the top", "Add color"]'::jsonb,0,'Finish care.','original'),
('127.153.d.2.E',4,'For proper care, a leather chair should be kept away from direct sunlight because sun can:','["Add shine", "Fade and dry the leather", "Make it heavier", "Make it wet"]'::jsonb,1,'Sun damages leather.','original'),
('127.153.d.3.A',3,'A room with clean lines, little ornament, and neutral colors is most likely in a:','["Rococo style", "Victorian style", "Contemporary style", "Baroque style"]'::jsonb,2,'Contemporary favors simplicity.','original'),
('127.153.d.3.A',4,'Heavy carved wood, rich fabrics, and ornate detail are typical of:','["Scandinavian style", "Minimalist style", "Industrial style", "Traditional style"]'::jsonb,3,'Traditional is ornate.','original'),
('127.153.d.3.B',3,'Task lighting, such as a reading lamp, is placed to:','["Provide light for a specific activity", "Warm the floor", "Hide the room", "Reduce light"]'::jsonb,0,'Task lighting supports tasks.','original'),
('127.153.d.3.B',4,'A designer adds a mirror across from a window to:','["Reduce ceiling height", "Reflect light and make the room feel larger", "Add noise", "Block daylight"]'::jsonb,1,'Mirrors bounce light.','original'),
('127.153.d.3.C',3,'A sustainable interior material is one that:','["Cannot be recycled", "Is rare and imported", "Is renewable or has low environmental impact", "Is made with toxic glue"]'::jsonb,2,'Eco-friendly choices.','original'),
('127.153.d.3.C',4,'Bamboo flooring is often promoted as eco-friendly because it:','["Takes decades to regrow", "Is made of plastic", "Cannot be harvested", "Grows back quickly"]'::jsonb,3,'Bamboo is rapidly renewable.','original'),
('127.153.d.3.D',3,'For a window that needs privacy but should still let in light, a good choice is:','["Sheer curtains or light-filtering shades", "A painted-over pane", "Solid steel shutters", "Brick"]'::jsonb,0,'Filtering shades balance both.','original'),
('127.153.d.3.D',4,'Window treatments hung from a rod close to the ceiling make the window look:','["Shorter", "Taller", "Darker", "Narrower"]'::jsonb,1,'Mounting high lengthens the window.','original'),
('127.153.d.3.E',3,'When accessorizing a room on a tight budget, a designer should first set:','["A sale date", "A color wheel", "A spending limit", "A guest list"]'::jsonb,2,'Budget first.','original'),
('127.153.d.3.E',4,'A cost-saving way to accessorize is to:','["Skip all accessories", "Replace every item", "Buy the most expensive item", "Reuse and rearrange items the client already owns"]'::jsonb,3,'Reuse saves money.','original'),
('127.153.d.3.F',3,'Paint, wallpaper, and paneling are examples of:','["Wall treatments", "Floor coverings", "Light fixtures", "Window hardware"]'::jsonb,0,'Wall treatment types.','original'),
('127.153.d.3.F',4,'A semi-gloss paint is often chosen for kitchens and baths because it is:','["Always cheapest", "Easier to clean and moisture resistant", "Harder to wipe", "Rougher"]'::jsonb,1,'Higher sheen washes well.','original'),
('127.153.d.3.G',3,'Hardwood, tile, and carpet are types of:','["Ceiling fans", "Wall paint", "Flooring", "Shelving"]'::jsonb,2,'Flooring options.','original'),
('127.153.d.3.G',4,'Ceramic tile is a good floor choice for a bathroom because it is:','["Fragile to moisture", "Flammable", "Soaks up water", "Water resistant"]'::jsonb,3,'Tile resists moisture.','original'),
('127.153.d.4.A',3,'A sofa, a dining table, and a refrigerator are examples of:','["Furniture and equipment", "Floor plans", "Accessories only", "Wall treatments"]'::jsonb,0,'Furnishings and equipment.','original'),
('127.153.d.4.A',4,'Equipment such as a dishwasher differs from furniture because it:','["Is always decorative", "Performs a function using power or plumbing", "Has no cost", "Cannot be moved"]'::jsonb,1,'Equipment is functional.','original'),
('127.153.d.4.B',3,'A family with a toddler would most likely choose furniture that is:','["Fragile with sharp corners", "Very tall", "Durable with rounded edges", "Glass and delicate"]'::jsonb,2,'Child safe choices.','original'),
('127.153.d.4.B',4,'A retired couple downsizing might prefer furniture that is:','["Tiny and fragile", "Hard to enter", "Oversized and heavy", "Comfortable, smaller, and easy to move"]'::jsonb,3,'Needs change with life stage.','original'),
('127.153.d.4.C',3,'An important economic factor in choosing a dining set is:','["The total cost compared to the budget", "The store sign", "Its nickname", "The photo size"]'::jsonb,0,'Cost matters.','original'),
('127.153.d.4.C',4,'Buying a quality sofa that lasts ten years can cost less over time than replacing a cheap one every:','["Twenty years", "Two or three years", "Ten years", "Fifty years"]'::jsonb,1,'Cost per year.','original'),
('127.153.d.4.D',3,'Before placing furniture, a designer measures the room and draws a:','["Resume", "Menu", "Floor plan", "Logo"]'::jsonb,2,'Floor plans guide layout.','original'),
('127.153.d.4.D',4,'To keep a traffic path through a room, a designer leaves about how much clear walkway?','["None", "About 30 feet", "About 3 inches", "About 3 feet"]'::jsonb,3,'Walkways need space.','original'),
('127.153.d.4.E',3,'A client who uses a wheelchair needs furniture arranged to allow:','["Wide clear paths for turning", "Stacked boxes", "Low light", "Narrow gaps"]'::jsonb,0,'Accessibility.','original'),
('127.153.d.4.E',4,'Adjustable-height desks and chairs accommodate:','["Only pets", "People of different heights and needs", "Only children", "Only one user"]'::jsonb,1,'Flexible furniture.','original'),
('127.153.d.4.F',3,'Smart-home devices that dim lights by voice are an example of:','["A sewing pattern", "A hand tool", "Technology in furnishings", "A paint color"]'::jsonb,2,'Tech trends.','original'),
('127.153.d.4.F',4,'A good way to research furnishing trends is to read:','["Weather maps", "Gossip", "Lottery tickets", "Trade magazines and industry reports"]'::jsonb,3,'Reliable sources.','original'),
('127.153.d.5.A',3,'Using safety rules in a showroom workplace includes keeping aisles:','["Clear of boxes and cords", "Dark", "Blocked", "Wet"]'::jsonb,0,'Safe aisles.','original'),
('127.153.d.5.A',4,'Lifting a heavy box of furnishings safely means bending the:','["Back and keeping knees locked", "Knees and keeping the back straight", "Neck only", "Elbows only"]'::jsonb,1,'Safe lifting.','original'),
('127.153.d.5.B',3,'A frayed power cord on a floor lamp is a:','["Design feature", "Cleaning tool", "Fire and shock hazard", "Safety feature"]'::jsonb,2,'Identify hazards.','original'),
('127.153.d.5.B',4,'A rug with curled edges in a hallway is a potential:','["Fire exit", "Light source", "Cooling vent", "Trip hazard"]'::jsonb,3,'Falls.','original'),
('127.153.d.5.C',3,'Preventing accidents in a workshop includes wearing:','["Proper protective gear", "Open sandals", "Loose scarves", "Headphones at high volume"]'::jsonb,0,'Prevention.','original'),
('127.153.d.5.C',4,'A good prevention habit is to store heavy items:','["In walkways", "On lower shelves", "On chairs", "On the top shelf"]'::jsonb,1,'Store heavy low.','original'),
('127.153.d.5.D',3,'OSHA is a federal agency that sets rules for:','["Fashion trends", "Sports teams", "Workplace safety and health", "Movie ratings"]'::jsonb,2,'OSHA basics.','original'),
('127.153.d.5.D',4,'Safety Data Sheets must be kept so workers can find information about:','["Lunch menus", "Sales goals", "Paint colors", "Hazardous chemicals"]'::jsonb,3,'Right to know.','original'),
('127.153.d.5.E',3,'If a small fire starts in a stockroom, the first priority is to:','["Alert others and get to safety", "Take photos", "Move furniture", "Finish the sale"]'::jsonb,0,'Emergency response.','original'),
('127.153.d.5.E',4,'The PASS method for using a fire extinguisher begins with:','["Push the wall", "Pull the pin", "Pour water", "Pick up the phone"]'::jsonb,1,'PASS: Pull, Aim, Squeeze, Sweep.','original'),
('127.153.d.5.F',3,'A business protects the environment by recycling:','["Only gold", "Nothing", "Packaging and scrap materials", "Only food"]'::jsonb,2,'Recycling.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
