('127.153.d.12.B',3,'An ethical designer is honest about:','["Fake reviews", "False claims", "Costs and materials", "Hiding fees"]'::jsonb,2,'Ethics.','original'),
('127.153.d.12.B',4,'Recommending a product only because it pays you a hidden commission is:','["Required", "Smart", "Legal advice", "Unethical"]'::jsonb,3,'Conflict of interest.','original'),
('127.153.d.12.C',3,'Copyright law protects a designer''s original:','["Drawings and designs", "Uniform", "Tools", "Receipts"]'::jsonb,0,'Legal aspects.','original'),
('127.153.d.12.C',4,'A written contract between a designer and client helps by clearly stating:','["The weather", "The scope of work and payment terms", "The client''s hobbies", "The designer''s age"]'::jsonb,1,'Contract.','original'),
('127.154.d.1.A',3,'In an interior design practicum, a student speaking with a client should:','["Avoid eye contact", "Use only jargon", "Use clear, consistent language and tone", "Mumble"]'::jsonb,2,'Communication.','original'),
('127.154.d.1.A',4,'Matching your facial expression to your words is an example of consistent:','["Paperwork", "Billing", "Shipping", "Verbal and nonverbal communication"]'::jsonb,3,'Consistency.','original'),
('127.154.d.1.B',3,'Active listening with a client includes:','["Asking follow-up questions", "Interrupting", "Looking away", "Checking your phone"]'::jsonb,0,'Clarify information.','original'),
('127.154.d.1.B',4,'After a client describes their needs, you can confirm understanding by:','["Changing the subject", "Restating the main points", "Ending the call", "Ignoring details"]'::jsonb,1,'Paraphrase.','original'),
('127.154.d.1.C',3,'A formal presentation to a client usually follows a:','["Rumor", "Silent slide", "Planned structure with visuals", "Random order"]'::jsonb,2,'Presentations.','original'),
('127.154.d.1.C',4,'An informal presentation might be a quick:','["Board meeting", "Public award show", "Press conference", "Desk review of a sample board with a coworker"]'::jsonb,3,'Informal.','original'),
('127.154.d.1.D',3,'Measuring a room and recording dimensions is an example of communicating:','["Technical data", "Slogans", "Poetry", "Gossip"]'::jsonb,0,'Interpret data.','original'),
('127.154.d.1.D',4,'A chart comparing costs of three flooring options helps a client:','["Ignore the price", "Make an informed choice", "Avoid choosing", "Delay forever"]'::jsonb,1,'Communicate data.','original'),
('127.154.d.1.E',3,'If a client looks confused during a presentation, the designer should:','["Speak faster", "Walk away", "Pause and ask what is unclear", "Ignore it"]'::jsonb,2,'Read cues.','original'),
('127.154.d.1.E',4,'A client crossing arms and frowning might be signaling:','["Boredom with lunch", "Agreement", "Excitement", "Disagreement or discomfort"]'::jsonb,3,'Interpret cues.','original'),
('127.154.d.2.A',3,'Using critical thinking on a project means:','["Analyzing options before deciding", "Guessing", "Hurrying", "Copying"]'::jsonb,0,'Critical thinking.','original'),
('127.154.d.2.A',4,'A team that debates two layout plans using evidence is exercising:','["Delay", "Collaborative critical thinking", "Avoidance", "Luck"]'::jsonb,1,'Team critical thinking.','original'),
('127.154.d.2.B',3,'A client''s tiny room needs more storage. A creative solution is to:','["Add more clutter", "Remove all furniture", "Use built-in or multi-purpose furniture", "Paint the ceiling"]'::jsonb,2,'Innovative solutions.','original'),
('127.154.d.2.B',4,'To break down a design problem, a designer first:','["Buys furniture", "Paints walls", "Orders carpet", "Lists the client''s needs and constraints"]'::jsonb,3,'Analyze problem.','original'),
('127.154.d.2.C',3,'Technical research for choosing flooring may include:','["Manufacturer specification sheets", "Luck", "Mood", "Rumors"]'::jsonb,0,'Research.','original'),
('127.154.d.2.C',4,'To decide whether a fabric is flame-resistant, check the:','["Store sign", "Manufacturer''s test data and labels", "Color", "Price tag"]'::jsonb,1,'Reliable data.','original'),
('127.154.d.3.A',3,'Safety in an interior design studio includes keeping sample cords and tools:','["Plugged in always", "Hidden in boxes", "Organized and out of walkways", "Strewn on the floor"]'::jsonb,2,'Studio safety.','original'),
('127.154.d.3.A',4,'Before handling unfamiliar finishing products, a designer reads the:','["Price tag", "Brochure", "Color chart", "Safety data sheet"]'::jsonb,3,'Follow rules.','original'),
('127.154.d.3.B',3,'When moving heavy samples, the safest way is to:','["Lift with your legs or ask for help", "Drag over feet", "Throw them", "Jerk with your back"]'::jsonb,0,'Safe procedures.','original'),
('127.154.d.3.B',4,'An emergency exit in a studio must remain:','["Locked", "Unobstructed", "Hidden", "Blocked by boxes"]'::jsonb,1,'Procedures.','original'),
('127.154.d.3.C',3,'Skillful tool care includes returning tools to:','["The floor", "Another room", "Their proper storage places", "A friend''s car"]'::jsonb,2,'Tool care.','original'),
('127.154.d.3.C',4,'A dull utility knife is more dangerous than a sharp one because it:','["Is safer", "Cuts better", "Is lighter", "Requires more force and may slip"]'::jsonb,3,'Skillful use.','original'),
('127.154.d.4.A',3,'A positive work ethic means performing assigned tasks:','["On time and with care", "Carelessly", "Never", "Late"]'::jsonb,0,'Work ethic.','original'),
('127.154.d.4.A',4,'A student who volunteers to help organize the sample library shows:','["Apathy", "Initiative", "Disrespect", "Laziness"]'::jsonb,1,'Initiative.','original'),
('127.154.d.4.B',3,'Ethical reasoning means asking whether a decision is:','["Easy only", "Fast only", "Honest and fair to everyone affected", "Cheap only"]'::jsonb,2,'Ethical decisions.','original'),
('127.154.d.4.B',4,'A client asks you to claim an item is solid wood when it is veneer. You should:','["Change the price", "Lie", "Hide the label", "Refuse and state the truth"]'::jsonb,3,'Honesty.','original'),
('127.154.d.4.C',3,'Ethical practice in the furnishing industry includes:','["Giving accurate product information", "Misleading ads", "Hiding defects", "Fake discounts"]'::jsonb,0,'Industry ethics.','original'),
('127.154.d.4.C',4,'Crediting a manufacturer for its design in a presentation is:','["Illegal", "An ethical practice", "Pointless", "Required by paint"]'::jsonb,1,'Credit.','original'),
('127.154.d.4.D',3,'Complying with building and safety codes means:','["Ignoring them", "Following them sometimes", "Following them on every project", "Avoiding inspections"]'::jsonb,2,'Compliance.','original'),
('127.154.d.4.D',4,'If a selected sofa does not meet the fire code for a public space, the designer should:','["Ignore the code", "Change the client''s mind", "Hide the label", "Choose a compliant alternative"]'::jsonb,3,'Comply.','original'),
('127.154.d.5.A',3,'In a supervised internship, a student records:','["Tasks, hours, and what was learned", "Gossip", "Songs", "Jokes"]'::jsonb,0,'Document learning.','original'),
('127.154.d.5.A',4,'A supervisor evaluates a practicum student through:','["Weather", "Observation and the student''s documentation", "Rumors", "Guessing"]'::jsonb,1,'Evaluate.','original'),
('127.154.d.5.B',3,'Advanced technical skills for a designer include:','["Gardening", "Juggling", "Space planning and reading construction plans", "Singing"]'::jsonb,2,'Advanced skills.','original'),
('127.154.d.5.B',4,'Using a scale ruler to read a floor plan is part of advanced:','["Sports", "Cooking", "Karaoke", "Technical knowledge"]'::jsonb,3,'Technical.','original'),
('127.154.d.5.C',3,'Applying principles of design to a room scheme means arranging elements for:','["Balance and harmony", "Clutter", "Randomness", "Confusion"]'::jsonb,0,'Design application.','original'),
('127.154.d.5.C',4,'A room that feels top-heavy might be improved by adding:','["More ceiling decor", "Visual weight near the floor", "Tall bare walls", "Fewer rugs"]'::jsonb,1,'Balance.','original'),
('127.154.d.5.D',3,'Evaluating materials and workmanship on a client''s chair includes checking the:','["Store logo", "Sticker", "Frame, joints, and fabric", "Shipping label"]'::jsonb,2,'Quality.','original'),
('127.154.d.5.D',4,'Wobbly legs and loose joints indicate poor:','["Paint", "Fabric", "Lighting", "Construction quality"]'::jsonb,3,'Workmanship.','original'),
('127.154.d.5.E',3,'Advanced care of a natural stone countertop includes using:','["A pH-neutral cleaner and a sealer as needed", "Steel wool", "Harsh acid", "Bleach daily"]'::jsonb,0,'Care procedures.','original'),
('127.154.d.5.E',4,'Acidic cleaners can damage marble because they:','["Add shine", "Etch the surface", "Seal it", "Dye it"]'::jsonb,1,'Chemistry of care.','original'),
('127.154.d.5.F',3,'Choosing accessories, lighting, and materials with advanced skill means considering:','["Color only", "Size only", "Function, style, and budget together", "Cost only"]'::jsonb,2,'Selection.','original'),
('127.154.d.5.F',4,'Layering ambient, task, and accent lighting creates a room that is:','["Dark", "Flat and dull", "Glaring", "Functional and visually interesting"]'::jsonb,3,'Lighting layers.','original'),
('127.154.d.5.G',3,'Arranging furniture to fit a floor plan starts with noting:','["Doors, windows, and traffic flow", "Price tags", "Brand names", "Wall color only"]'::jsonb,0,'Space planning.','original'),
('127.154.d.5.G',4,'A conversation area works best when seating is arranged:','["Across the room", "Facing each other within easy talking distance", "Back to back", "In a line against walls"]'::jsonb,1,'Furniture placement.','original'),
('127.154.d.5.H',3,'Applying knowledge of construction means selecting products that are:','["Fragile", "Cheapest only", "Well built and suited to their use", "Unfinished"]'::jsonb,2,'Application.','original'),
('127.154.d.5.H',4,'A durable commercial-grade fabric is chosen for a waiting room because it:','["Fades fast", "Stains easily", "Is delicate", "Withstands heavy use"]'::jsonb,3,'Selection.','original'),
('127.154.d.5.I',3,'Evaluating strengths and weaknesses of your skills helps you:','["Decide what to improve", "Hide errors", "Blame others", "Quit"]'::jsonb,0,'Self-evaluation.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_23_v1'
from (values
('127.154.d.5.I',4,'A student strong at design but slow at measuring should:','["Ignore it", "Practice measuring and drafting", "Skip plans", "Stop designing"]'::jsonb,1,'Targeted practice.','original'),
('127.154.d.5.J',3,'Representative work samples may include:','["Gossip", "Receipts", "Floor plans, mood boards, and photos", "Menus"]'::jsonb,2,'Samples.','original'),
('127.154.d.5.J',4,'A work sample is best when it shows:','["Nothing", "Random scribbles", "Blank paper", "Your skill and a clear design process"]'::jsonb,3,'Selection.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
